content:
{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "mechanism",
      "statement": "Heapsort is a sort algorithm that builds a heap, then repeatedly extracts the maximum item.",
      "start_line": 5,
      "end_line": 10
    },
    {
      "key": "obs_2",
      "facet": "property",
      "statement": "The run time of heapsort is O(n log n).",
      "start_line": 9,
      "end_line": 10
    },
    {
      "key": "obs_3",
      "facet": "relation",
      "statement": "Heapsort is a kind of in-place sort.",
      "start_line": 12,
      "end_line": 14
    },
    {
      "key": "obs_4",
      "facet": "relation",
      "statement": "Adaptive heap sort and smoothsort are specializations of heapsort.",
      "start_line": 16,
      "end_line": 21
    },
    {
      "key": "obs_5",
      "facet": "relation",
      "statement": "Build-heap, heap, and sift up are aggregate children of heapsort (parts of or used in it).",
      "start_line": 22,
      "end_line": 29
    },
    {
      "key": "obs_6",
      "facet": "mechanism",
      "statement": "Heapsort can be seen as a variant of selection sort in which sorted items are arranged in a heap to quickly find the next item.",
      "start_line": 33,
      "end_line": 38
    },
    {
      "key": "obs_7",
      "facet": "term",
      "statement": "Heapsort is sometimes called 'tournament sort' by analogy between a heap (with its heap property) and a tree of matches in a sports tournament.",
      "start_line": 39,
      "end_line": 41
    },
    {
      "key": "obs_8",
      "facet": "reference",
      "statement": "Robert W. Floyd published 'Algorithm 245 Treesort 3' in CACM, 7(12):701, December 1964.",
      "start_line": 64,
      "end_line": 67
    },
    {
      "key": "obs_9",
      "facet": "reference",
      "statement": "J. W. J. Williams published 'Algorithm 232 Heapsort' in CACM, 7(6):378-348, June 1964.",
      "start_line": 68,
      "end_line": 71
    },
    {
      "key": "obs_10",
      "facet": "other",
      "statement": "Although Williams clearly stated the idea of heapsort, Floyd gave a complete, efficient implementation nearly identical to what is used today.",
      "start_line": 72,
      "end_line": 72
    }
  ],
  "claims": [
    {
      "key": "claim_1",
      "status": "DERIVED_INTERPRETATION",
      "statement": "Heapsort combines the structural efficiency of a heap for finding extrema with the iterative extraction strategy of selection sort, resulting in an O(n log n) in-place sorting algorithm.",
      "supported_by": [
        "obs_1",
        "obs_2",
        "obs_3",
        "obs_6"
      ]
    },
    {
      "key": "claim_2",
      "status": "DERIVED_INTERPRETATION",
      "statement": "The modern standard implementation of heapsort is attributed to Robert W. Floyd, who provided the efficient complete implementation, while J. W. J. Williams is credited with stating the original idea.",
      "supported_by": [
        "obs_8",
        "obs_9",
        "obs_10"
      ]
    }
  ],
  "questions": []
}
